"use client"

import { createContext, useContext, useState, useEffect, type ReactNode } from "react"

interface User {
  id: string
  name: string
  email: string
  avatar?: string
  phone?: string
  address?: string
  city: string
}

interface AuthContextType {
  user: User | null
  isAuthenticated: boolean
  login: (email: string, password: string) => Promise<void>
  logout: () => void
  updateUser: (data: Partial<User>) => void
}

const AuthContext = createContext<AuthContextType | undefined>(undefined)

// Mock user data
const mockUser: User = {
  id: "1",
  name: "Juan Dela Cruz",
  email: "juan.delacruz@email.com",
  phone: "+63 912 345 6789",
  address: "123 Main Street, Barangay San Vicente",
  city: "Calapan City Resident",
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null)
  const [isAuthenticated, setIsAuthenticated] = useState(false)

  // Load auth state from localStorage on mount
  useEffect(() => {
    const storedAuth = localStorage.getItem("calapan_auth")
    if (storedAuth === "true") {
      setUser(mockUser)
      setIsAuthenticated(true)
    }
  }, [])

  const login = async (email: string, password: string) => {
    // Mock login - in production, this would call your Laravel API
    await new Promise((resolve) => setTimeout(resolve, 1000))
    setUser(mockUser)
    setIsAuthenticated(true)
    localStorage.setItem("calapan_auth", "true")
  }

  const logout = () => {
    setUser(null)
    setIsAuthenticated(false)
    localStorage.removeItem("calapan_auth")
  }

  const updateUser = (data: Partial<User>) => {
    if (user) {
      setUser({ ...user, ...data })
    }
  }

  return (
    <AuthContext.Provider value={{ user, isAuthenticated, login, logout, updateUser }}>{children}</AuthContext.Provider>
  )
}

export function useAuth() {
  const context = useContext(AuthContext)
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider")
  }
  return context
}
