"use client"
import Link from "next/link"
import { usePathname } from "next/navigation"
import { Home, Grid3x3, Newspaper, AlertTriangle, User } from "lucide-react"

export function BottomNav() {
  const pathname = usePathname()

  const navItems = [
    { icon: Home, label: "Home", href: "/" },
    { icon: Grid3x3, label: "Services", href: "/services" },
    { icon: Newspaper, label: "News", href: "/news" },
    { icon: AlertTriangle, label: "Emergency", href: "/emergency" },
    { icon: User, label: "Account", href: "/account" },
  ]

  return (
    <nav className="lg:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-4 py-3 z-50">
      <div className="flex items-center justify-around max-w-md mx-auto">
        {navItems.map((item) => {
          const isActive = pathname === item.href
          return (
            <Link key={item.href} href={item.href} className="flex flex-col items-center gap-1">
              <item.icon className={`w-6 h-6 ${isActive ? "text-orange-500" : "text-gray-400"}`} />
              <span className={`text-xs ${isActive ? "text-orange-500 font-semibold" : "text-gray-500"}`}>
                {item.label}
              </span>
            </Link>
          )
        })}
      </div>
    </nav>
  )
}
